async function db(){
 if(!pool)return;
 await pool.query(`CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password_hash TEXT NOT NULL,display_name VARCHAR(100) NOT NULL,full_name VARCHAR(100),channel_name VARCHAR(100),channel_description TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT NOW(),avatar_url TEXT DEFAULT NULL);
 CREATE TABLE IF NOT EXISTS videos(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(200) NOT NULL,description TEXT DEFAULT '',video_url TEXT NOT NULL,thumbnail_url TEXT,type VARCHAR(20) DEFAULT 'video',category VARCHAR(30) DEFAULT 'Vlog',views INTEGER DEFAULT 0,likes INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),upload_key TEXT UNIQUE,duration_seconds INTEGER DEFAULT 0);
 ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url TEXT; ALTER TABLE users ADD COLUMN IF NOT EXISTS is_admin BOOLEAN DEFAULT FALSE; ALTER TABLE users ADD COLUMN IF NOT EXISTS is_private BOOLEAN DEFAULT FALSE; ALTER TABLE users ADD COLUMN IF NOT EXISTS is_suspended BOOLEAN DEFAULT FALSE; ALTER TABLE users ADD COLUMN IF NOT EXISTS full_name VARCHAR(100); ALTER TABLE users ADD COLUMN IF NOT EXISTS channel_name VARCHAR(100); ALTER TABLE users ADD COLUMN IF NOT EXISTS channel_description TEXT DEFAULT ''; UPDATE users SET full_name=COALESCE(full_name,display_name),channel_name=COALESCE(channel_name,display_name) WHERE full_name IS NULL OR channel_name IS NULL; ALTER TABLE videos ADD COLUMN IF NOT EXISTS category VARCHAR(30) DEFAULT 'Vlog'; ALTER TABLE videos ADD COLUMN IF NOT EXISTS upload_key TEXT; CREATE UNIQUE INDEX IF NOT EXISTS videos_upload_key_uidx ON videos(upload_key) WHERE upload_key IS NOT NULL; CREATE TABLE IF NOT EXISTS subscriptions(subscriber_id INTEGER REFERENCES users(id) ON DELETE CASCADE,channel_id INTEGER REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(subscriber_id,channel_id));
 ALTER TABLE videos ADD COLUMN IF NOT EXISTS duration_seconds INTEGER DEFAULT 0;
 CREATE TABLE IF NOT EXISTS comments(id SERIAL PRIMARY KEY,video_id INTEGER REFERENCES videos(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,text TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
 CREATE TABLE IF NOT EXISTS watch_history(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,video_id INTEGER NOT NULL,watched_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(user_id,video_id));
 CREATE TABLE IF NOT EXISTS liked_videos(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,video_id INTEGER NOT NULL,liked_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(user_id,video_id));
 CREATE TABLE IF NOT EXISTS saved_videos(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,video_id INTEGER NOT NULL,saved_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(user_id,video_id)); CREATE TABLE IF NOT EXISTS saved_collections(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,name)); CREATE TABLE IF NOT EXISTS saved_collection_items(collection_id INTEGER REFERENCES saved_collections(id) ON DELETE CASCADE,video_id INTEGER NOT NULL,saved_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(collection_id,video_id)); CREATE TABLE IF NOT EXISTS ad_events(id SERIAL PRIMARY KEY,video_id INTEGER,kind VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW()); CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,type VARCHAR(40) NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,related_user_id INTEGER,related_video_id INTEGER,created_at TIMESTAMPTZ DEFAULT NOW(),read_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS notifications_user_created_idx ON notifications(user_id,created_at DESC);
 CREATE TABLE IF NOT EXISTS creator_wallets(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,enabled BOOLEAN DEFAULT FALSE,creator_share_bps INTEGER DEFAULT 7000 CHECK(creator_share_bps BETWEEN 0 AND 10000),balance_paise BIGINT DEFAULT 0,lifetime_earned_paise BIGINT DEFAULT 0,paid_out_paise BIGINT DEFAULT 0,updated_at TIMESTAMPTZ DEFAULT NOW());
 CREATE TABLE IF NOT EXISTS hyper_admin_wallet(id INTEGER PRIMARY KEY DEFAULT 1 CHECK(id=1),balance_paise BIGINT DEFAULT 0,lifetime_earned_paise BIGINT DEFAULT 0,paid_out_paise BIGINT DEFAULT 0,updated_at TIMESTAMPTZ DEFAULT NOW());
 INSERT INTO hyper_admin_wallet(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
 CREATE TABLE IF NOT EXISTS ad_revenue_ledger(id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,video_id INTEGER,provider VARCHAR(40) NOT NULL,external_event_id VARCHAR(180) UNIQUE NOT NULL,gross_paise BIGINT NOT NULL,creator_paise BIGINT NOT NULL,hyper_paise BIGINT NOT NULL,impressions INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW());
 CREATE TABLE IF NOT EXISTS payout_accounts(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,provider VARCHAR(40) NOT NULL DEFAULT 'razorpayx',contact_id VARCHAR(80),fund_account_id VARCHAR(80),status VARCHAR(30) DEFAULT 'pending',updated_at TIMESTAMPTZ DEFAULT NOW());
 CREATE TABLE IF NOT EXISTS payouts(id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,amount_paise BIGINT NOT NULL,provider VARCHAR(40) NOT NULL DEFAULT 'razorpayx',provider_payout_id VARCHAR(100),status VARCHAR(30) NOT NULL DEFAULT 'created',idempotency_key VARCHAR(120) UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),processed_at TIMESTAMPTZ);
 CREATE INDEX IF NOT EXISTS ad_revenue_ledger_user_created_idx ON ad_revenue_ledger(user_id,created_at DESC);
 CREATE INDEX IF NOT EXISTS payouts_user_created_idx ON payouts(user_id,created_at DESC); UPDATE creator_wallets SET creator_share_bps=7000 WHERE creator_share_bps<>7000; ${ADMIN_EMAIL ? `UPDATE users SET is_admin=TRUE WHERE LOWER(email)='${ADMIN_EMAIL.replace(/'/g,"''")}';` : ''}`);
}
const tok=u=>jwt.sign({id:u.id,username:u.username},SECRET,{expiresIn:'30d'});
function auth(req,res,next){const h=req.headers.authorization||'';try{req.user=jwt.verify(h.startsWith('Bearer ')?h.slice(7):'',SECRET);next()}catch{return res.status(401).json({message:'Login required'})}}

async function notifyUser(userId,type,title,message,relatedUserId=null,relatedVideoId=null){if(!pool||!userId)return;try{await pool.query('INSERT INTO notifications(user_id,type,title,message,related_user_id,related_video_id) VALUES($1,$2,$3,$4,$5,$6)',[userId,type,title,message,relatedUserId,relatedVideoId])}catch(e){console.warn('Notification failed:',e.message)}}
async function notifyAdmins(type,title,message,relatedUserId=null,relatedVideoId=null){if(!pool)return;try{const q=await pool.query('SELECT id FROM users WHERE is_admin=TRUE OR LOWER(email)=LOWER($1)',[ADMIN_EMAIL]);for(const r of q.rows)await notifyUser(r.id,type,title,message,relatedUserId,relatedVideoId)}catch(e){console.warn('Admin notification failed:',e.message)}}

const CREATOR_SHARE_BPS=7000; // Fixed HYPER revenue split: Creator 70% / HYPER Admin 30%
const MIN_WITHDRAWAL_PAISE=Math.max(100,Number(process.env.HYPER_MIN_WITHDRAWAL_PAISE||50000));
const MONETIZATION_LIVE=String(process.env.HYPER_MONETIZATION_ENABLED||'false').toLowerCase()==='true';
const RZP_KEY=process.env.RAZORPAYX_KEY_ID||'';
const RZP_SECRET=process.env.RAZORPAYX_KEY_SECRET||'';
const RZP_ACCOUNT=process.env.RAZORPAYX_ACCOUNT_NUMBER||'';
const ADMIN_KEY=process.env.HYPER_ADMIN_KEY||'';
const ADMIN_EMAIL=String(process.env.HYPER_ADMIN_EMAIL||'asarafalamt20@gmail.com').trim().toLowerCase();
function moneyPaise(v){return Math.round(Number(v||0));}
async function ensureWallet(userId){await pool.query('INSERT INTO creator_wallets(user_id,enabled,creator_share_bps) VALUES($1,$2,$3) ON CONFLICT(user_id) DO NOTHING',[userId,MONETIZATION_LIVE,CREATOR_SHARE_BPS]);}
function rzpAuth(){return 'Basic '+Buffer.from(RZP_KEY+':'+RZP_SECRET).toString('base64');}
async function rzp(pathname,options={}){if(!RZP_KEY||!RZP_SECRET)throw new Error('RazorpayX payout credentials are not configured');const r=await fetch('https://api.razorpay.com/v1'+pathname,{...options,headers:{Authorization:rzpAuth(),'Content-Type':'application/json',...(options.headers||{})}});const text=await r.text();let body={};try{body=JSON.parse(text)}catch{}if(!r.ok)throw new Error(body.error?.description||body.error?.reason||'RazorpayX request failed');return body;}
async function adminOnly(req,res,next){try{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});const h=req.headers.authorization||'';const raw=h.startsWith('Bearer ')?h.slice(7):'';if(!raw)return res.status(401).json({message:'HYPER login required'});req.user=jwt.verify(raw,SECRET);const q=await pool.query('SELECT id,email,is_admin FROM users WHERE id=$1',[req.user.id]);const email=String(q.rows[0]?.email||'').toLowerCase();const allowed=!!q.rows[0]?.is_admin || (!!ADMIN_EMAIL && email===ADMIN_EMAIL);if(!allowed)return res.status(403).json({message:'This HYPER account is not an Admin account'});next()}catch(e){return res.status(401).json({message:'Admin login required'})}}
app.get('/api/admin/channels',adminOnly,async(req,res)=>{if(!pool)return res.json([]);try{const q=await pool.query(`SELECT u.id,u.username,u.email,u.display_name,COALESCE(u.channel_name,u.display_name) channel_name,u.is_suspended,COALESCE(cw.enabled,FALSE) monetization_enabled,(SELECT COUNT(*) FROM videos v WHERE v.user_id=u.id)::int video_count,(SELECT COUNT(*) FROM subscriptions s WHERE s.channel_id=u.id)::int subscriber_count FROM users u LEFT JOIN creator_wallets cw ON cw.user_id=u.id ORDER BY u.created_at DESC LIMIT 500`);res.json(q.rows)}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/admin/channels/:id/monetization',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected'});try{const uid=Number(req.params.id),enabled=!!req.body.enabled;await pool.query(`INSERT INTO creator_wallets(user_id,enabled,creator_share_bps) VALUES($1,$2,7000) ON CONFLICT(user_id) DO UPDATE SET enabled=EXCLUDED.enabled,creator_share_bps=7000,updated_at=NOW()`,[uid,enabled]);await notifyUser(uid,'monetization',`Monetization ${enabled?'ON':'OFF'}`,`HYPER Admin has turned your channel monetization ${enabled?'ON':'OFF'}. Creator share remains 70%.`,req.user.id);res.json({ok:true,enabled,creator_share_percent:70})}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/admin/channels/:id/suspend',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected'});try{const uid=Number(req.params.id),suspended=!!req.body.suspended;if(uid===req.user.id)return res.status(400).json({message:'Admin account cannot suspend itself'});await pool.query('UPDATE users SET is_suspended=$1 WHERE id=$2',[suspended,uid]);await notifyUser(uid,'admin_action',`Channel ${suspended?'suspended':'restored'}`,`HYPER Admin has ${suspended?'suspended':'restored'} your channel.`,req.user.id);res.json({ok:true,is_suspended:suspended})}catch(e){res.status(500).json({message:e.message})}});
app.get('/api/admin/videos',adminOnly,async(req,res)=>{if(!pool)return res.json([]);try{const q=await pool.query(`SELECT v.id,v.title,v.type,v.category,v.views,v.likes,v.created_at,v.user_id,u.username,COALESCE(u.channel_name,u.display_name) channel_name FROM videos v JOIN users u ON u.id=v.user_id ORDER BY v.created_at DESC LIMIT 300`);res.json(q.rows)}catch(e){res.status(500).json({message:e.message})}});
app.delete('/api/admin/videos/:id',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected'});try{const q=await pool.query('SELECT v.id,v.video_url,v.thumbnail_url,v.user_id,v.title FROM videos v WHERE v.id=$1',[req.params.id]);if(!q.rows[0])return res.status(404).json({message:'Video not found'});const v=q.rows[0];await pool.query('DELETE FROM videos WHERE id=$1',[v.id]);for(const u of [v.video_url,v.thumbnail_url]){if(u&&String(u).startsWith('/uploads/')){try{fs.unlinkSync(path.join(dir,String(u).replace(/^\/uploads\//,'')))}catch{}}else await deletePermanent(u)}await notifyUser(v.user_id,'admin_action','Video removed by HYPER Admin',`Your video “${v.title}” was removed by HYPER Admin.`,req.user.id,v.id);res.json({ok:true})}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/admin/message',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected'});try{const uid=Number(req.body.user_id),title=String(req.body.title||'HYPER Admin message').trim().slice(0,180),message=String(req.body.message||'').trim();if(!uid||!message)return res.status(400).json({message:'user_id and message are required'});await notifyUser(uid,'admin_message',title,message,req.user.id);res.json({ok:true})}catch(e){res.status(500).json({message:e.message})}});
