app.post('/api/me/saved-collections/:id/videos/:videoId',auth,async(req,res)=>{if(!pool)return res.json({saved:true});try{let c=await pool.query('SELECT id FROM saved_collections WHERE id=$1 AND user_id=$2',[req.params.id,req.user.id]);if(!c.rowCount)return res.status(404).json({message:'Save file not found'});await pool.query('INSERT INTO saved_collection_items(collection_id,video_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[req.params.id,req.params.videoId]);res.json({saved:true})}catch(e){res.status(500).json({message:e.message})}});
app.delete('/api/me/saved-collections/:id/videos/:videoId',auth,async(req,res)=>{if(!pool)return res.json({saved:false});try{await pool.query('DELETE FROM saved_collection_items i USING saved_collections c WHERE i.collection_id=c.id AND c.id=$1 AND c.user_id=$2 AND i.video_id=$3',[req.params.id,req.user.id,req.params.videoId]);res.json({saved:false})}catch(e){res.status(500).json({message:e.message})}});



app.get('/api/studio/earnings',auth,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});try{await ensureWallet(req.user.id);const [w,l,p]=await Promise.all([pool.query('SELECT enabled,creator_share_bps,balance_paise,lifetime_earned_paise,paid_out_paise FROM creator_wallets WHERE user_id=$1',[req.user.id]),pool.query('SELECT provider,external_event_id,gross_paise,creator_paise,hyper_paise,impressions,created_at FROM ad_revenue_ledger WHERE user_id=$1 ORDER BY created_at DESC LIMIT 100',[req.user.id]),pool.query('SELECT amount_paise,provider,provider_payout_id,status,created_at,processed_at FROM payouts WHERE user_id=$1 ORDER BY created_at DESC LIMIT 50',[req.user.id])]);let x=w.rows[0];res.json({monetization:{enabled:!!x.enabled,creator_share_percent:Number(x.creator_share_bps)/100,balance:Number(x.balance_paise)/100,lifetime_earned:Number(x.lifetime_earned_paise)/100,paid_out:Number(x.paid_out_paise)/100,min_withdrawal:MIN_WITHDRAWAL_PAISE/100},ledger:l.rows.map(r=>({...r,gross:Number(r.gross_paise)/100,creator:Number(r.creator_paise)/100,hyper:Number(r.hyper_paise)/100})),payouts:p.rows.map(r=>({...r,amount:Number(r.amount_paise)/100}))})}catch(e){res.status(500).json({message:e.message})}});
app.get('/api/studio/payout-account',auth,async(req,res)=>{if(!pool)return res.json({configured:false});try{let q=await pool.query('SELECT provider,contact_id,fund_account_id,status,updated_at FROM payout_accounts WHERE user_id=$1',[req.user.id]);res.json({configured:!!q.rows[0]?.fund_account_id,status:q.rows[0]?.status||'not_configured',provider:q.rows[0]?.provider||'razorpayx'})}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/studio/payout-account',auth,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});try{const fund=String(req.body.fund_account_id||'').trim();const contact=String(req.body.contact_id||'').trim();if(!fund)return res.status(400).json({message:'RazorpayX fund account ID is required'});await pool.query(`INSERT INTO payout_accounts(user_id,provider,contact_id,fund_account_id,status,updated_at) VALUES($1,'razorpayx',$2,$3,'ready',NOW()) ON CONFLICT(user_id) DO UPDATE SET contact_id=EXCLUDED.contact_id,fund_account_id=EXCLUDED.fund_account_id,status='ready',updated_at=NOW()`,[req.user.id,contact||null,fund]);res.json({ok:true,status:'ready'})}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/studio/withdraw',auth,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});const client=await pool.connect();try{const amount=moneyPaise(req.body.amount_paise);if(!Number.isFinite(amount)||amount<MIN_WITHDRAWAL_PAISE)return res.status(400).json({message:`Minimum withdrawal is ₹${(MIN_WITHDRAWAL_PAISE/100).toFixed(2)}`});await client.query('BEGIN');await client.query('SELECT pg_advisory_xact_lock($1)',[req.user.id]);await ensureWallet(req.user.id);const w=(await client.query('SELECT balance_paise FROM creator_wallets WHERE user_id=$1 FOR UPDATE',[req.user.id])).rows[0];if(Number(w.balance_paise)<amount){await client.query('ROLLBACK');return res.status(400).json({message:'Insufficient available balance'});}const pa=(await client.query('SELECT fund_account_id FROM payout_accounts WHERE user_id=$1 AND status=\'ready\'',[req.user.id])).rows[0];if(!pa?.fund_account_id){await client.query('ROLLBACK');return res.status(400).json({message:'Set up your payout account first'});}if(!RZP_KEY||!RZP_SECRET||!RZP_ACCOUNT){await client.query('ROLLBACK');return res.status(503).json({message:'RazorpayX live payout configuration is not complete'});}const idem=crypto.randomUUID();const row=(await client.query('INSERT INTO payouts(user_id,amount_paise,provider,status,idempotency_key) VALUES($1,$2,\'razorpayx\',\'created\',$3) RETURNING id',[req.user.id,amount,idem])).rows[0];await client.query('UPDATE creator_wallets SET balance_paise=balance_paise-$1,paid_out_paise=paid_out_paise+$1,updated_at=NOW() WHERE user_id=$2',[amount,req.user.id]);await client.query('COMMIT');let rp;try{rp=await rzp('/payouts',{method:'POST',headers:{'X-Payout-Idempotency':idem},body:JSON.stringify({account_number:RZP_ACCOUNT,fund_account_id:pa.fund_account_id,amount,currency:'INR',mode:String(req.body.mode||'IMPS').toUpperCase(),purpose:'payout',queue_if_low_balance:true,reference_id:'HYPER-'+row.id})})}catch(e){await pool.query('UPDATE payouts SET status=\'failed\',processed_at=NOW() WHERE id=$1',[row.id]);await pool.query('UPDATE creator_wallets SET balance_paise=balance_paise+$1,paid_out_paise=GREATEST(paid_out_paise-$1,0),updated_at=NOW() WHERE user_id=$2',[amount,req.user.id]);return res.status(502).json({message:e.message})}await pool.query('UPDATE payouts SET provider_payout_id=$1,status=$2,processed_at=NOW() WHERE id=$3',[rp.id||null,rp.status||'processing',row.id]);res.json({ok:true,payout_id:rp.id,status:rp.status||'processing',amount:amount/100})}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(500).json({message:e.message})}finally{client.release()}});
app.post('/api/admin/monetization/enable',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});try{const uid=Number(req.body.user_id);const enabled=req.body.enabled!==false;const share=7000; await pool.query(`INSERT INTO creator_wallets(user_id,enabled,creator_share_bps) VALUES($1,$2,$3) ON CONFLICT(user_id) DO UPDATE SET enabled=EXCLUDED.enabled,creator_share_bps=EXCLUDED.creator_share_bps,updated_at=NOW()`,[uid,enabled,share]);await notifyUser(uid,'monetization',`Monetization ${enabled?'ON':'OFF'}`,`HYPER Admin has turned your channel monetization ${enabled?'ON':'OFF'}. Creator share remains 70%.`,req.user.id);res.json({ok:true,enabled,creator_share_percent:share/100})}catch(e){res.status(500).json({message:e.message})}});
app.get('/api/admin/monetization/summary',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});try{const [t,u,d,w]=await Promise.all([pool.query(`SELECT COALESCE(SUM(gross_paise),0) gross_paise,COALESCE(SUM(creator_paise),0) creator_paise,COALESCE(SUM(hyper_paise),0) hyper_paise,COALESCE(SUM(impressions),0) impressions,COUNT(*)::int events FROM ad_revenue_ledger`),pool.query(`SELECT u.id,u.username,COALESCE(u.channel_name,u.display_name,u.username) channel_name,COALESCE(SUM(l.gross_paise),0) gross_paise,COALESCE(SUM(l.creator_paise),0) creator_paise,COALESCE(SUM(l.hyper_paise),0) hyper_paise,COALESCE(SUM(l.impressions),0) impressions FROM users u LEFT JOIN ad_revenue_ledger l ON l.user_id=u.id GROUP BY u.id,u.username,u.channel_name,u.display_name HAVING COUNT(l.id)>0 ORDER BY hyper_paise DESC LIMIT 200`),pool.query(`SELECT DATE_TRUNC('day',created_at)::date AS "day",COALESCE(SUM(gross_paise),0) gross_paise,COALESCE(SUM(creator_paise),0) creator_paise,COALESCE(SUM(hyper_paise),0) hyper_paise FROM ad_revenue_ledger GROUP BY 1 ORDER BY 1 DESC LIMIT 90`),pool.query(`SELECT balance_paise,lifetime_earned_paise,paid_out_paise FROM hyper_admin_wallet WHERE id=1`)]);let x=t.rows[0],a=w.rows[0]||{balance_paise:0,lifetime_earned_paise:0,paid_out_paise:0};res.json({split:{creator_percent:70,hyper_admin_percent:30},wallet:{balance:Number(a.balance_paise||0)/100,lifetime_earned:Number(a.lifetime_earned_paise||0)/100,paid_out:Number(a.paid_out_paise||0)/100},totals:{gross:Number(x.gross_paise)/100,creator:Number(x.creator_paise)/100,hyper_admin:Number(x.hyper_paise)/100,impressions:Number(x.impressions||0),events:Number(x.events||0)},creators:u.rows.map(r=>({id:r.id,username:r.username,channel_name:r.channel_name,gross:Number(r.gross_paise)/100,creator:Number(r.creator_paise)/100,hyper_admin:Number(r.hyper_paise)/100,impressions:Number(r.impressions||0)})),daily:d.rows.map(r=>({day:r.day,gross:Number(r.gross_paise)/100,creator:Number(r.creator_paise)/100,hyper_admin:Number(r.hyper_paise)/100}))})}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/admin/monetization/revenue',adminOnly,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});const client=await pool.connect();try{const uid=Number(req.body.user_id),gross=moneyPaise(req.body.gross_paise),impressions=Math.max(0,Number(req.body.impressions||0)),provider=String(req.body.provider||'ad-network').slice(0,40),external=String(req.body.external_event_id||'').trim(),videoId=req.body.video_id?Number(req.body.video_id):null;if(!uid||gross<=0||!external)return res.status(400).json({message:'user_id, gross_paise and external_event_id are required'});await client.query('BEGIN');await client.query('SELECT pg_advisory_xact_lock($1)',[uid]);await ensureWallet(uid);let w=(await client.query('SELECT enabled,creator_share_bps FROM creator_wallets WHERE user_id=$1 FOR UPDATE',[uid])).rows[0];if(!w?.enabled)return res.status(400).json({message:'Creator monetization is not enabled'});let creator=Math.floor(gross*Number(w.creator_share_bps)/10000),hyper=gross-creator;const ins=await client.query(`INSERT INTO ad_revenue_ledger(user_id,video_id,provider,external_event_id,gross_paise,creator_paise,hyper_paise,impressions) VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT(external_event_id) DO NOTHING RETURNING id`,[uid,videoId,provider,external,gross,creator,hyper,impressions]);if(ins.rowCount){await client.query('UPDATE creator_wallets SET balance_paise=balance_paise+$1,lifetime_earned_paise=lifetime_earned_paise+$1,updated_at=NOW() WHERE user_id=$2',[creator,uid]);await client.query('UPDATE hyper_admin_wallet SET balance_paise=balance_paise+$1,lifetime_earned_paise=lifetime_earned_paise+$1,updated_at=NOW() WHERE id=1',[hyper])}await client.query('COMMIT');res.json({ok:true,credited:!!ins.rowCount,creator_paise:creator,hyper_paise:hyper})}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(500).json({message:e.message})}finally{client.release()}});
app.get('/api/videos/:id/comments',async(req,res)=>{if(!pool)return res.json([]);try{let q=await pool.query('SELECT c.id,c.text,c.created_at,u.display_name FROM comments c JOIN users u ON u.id=c.user_id WHERE c.video_id=$1 ORDER BY c.created_at DESC LIMIT 100',[req.params.id]);res.json(q.rows)}catch(e){res.status(500).json({message:e.message})}});
app.post('/api/videos/:id/comments',auth,async(req,res)=>{if(!pool)return res.status(503).json({message:'Database is not connected on the server'});try{let q=await pool.query('INSERT INTO comments(video_id,user_id,text) VALUES($1,$2,$3) RETURNING id,text,created_at',[req.params.id,req.user.id,String(req.body.text||'').trim()]);res.json(q.rows[0])}catch(e){res.status(500).json({message:e.message})}});
app.use((err,req,res,next)=>{if(err instanceof multer.MulterError){return res.status(400).json({message:err.code==='LIMIT_FILE_SIZE'?'Video is too large (max 250 MB).':err.message})}if(err)return res.status(400).json({message:err.message||'Upload failed'});next()});
